L3_1 = "\231\167\129\227\130\136\227\128\130\227\129\130\227\129\170\227\129\159\227\128\129\228\187\138\230\151\165\229\134\141\229\176\177\232\129\183\227\129\174\233\157\162\230\142\165\227\129\160\227\129\163\227\129\159\227\129\167\227\129\151\227\130\135\239\188\159\227\128\128\227\129\169\227\129\134\239\188\159\227\128\128\227\129\134\227\129\190\227\129\143\227\129\132\227\129\163\227\129\159\239\188\159"
